import {initializeWorldUI,setWorldActive} from './world-ui.js';
import {labs,topics,cloudServices} from './data.js';
import {clamp,initialProgress,getRecord,markVisited,markTask,isComplete,parseProgress,matchingTopics,canAdvance,resolveModel} from './core.js';
import {ArchitectureModel} from './model.js';
import {initializeStudy,openTopic,renderRoadmap,learningProgressReport,resetLearning} from './study.js';
import {connectionDetails} from './network.js';
const $=id=>document.getElementById(id),key='devops-universe-progress-v1';
const el=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
let storageAvailable=true,progress;try{progress=parseProgress(localStorage.getItem(key),labs);}catch{progress=initialProgress();storageAvailable=false;}
let current=labs[0],index=0,selected=current.nodes[0].id,playing=false,failed=false,timer=null,quizSolved=false,resetArmed=false;
const model=new ArchitectureModel($('model'),$('node-labels'),selectNode,step=>{stop();go(step);$('connection-panel').open=true;});
function save(){try{localStorage.setItem(key,JSON.stringify(progress));storageAvailable=true;}catch{storageAvailable=false;}renderProgress();}
function stop(){playing=false;clearTimeout(timer);timer=null;$('play').textContent='▶ Play journey';model.update({playing:false});}
function schedule(){clearTimeout(timer);timer=setTimeout(()=>{if(!playing)return;if(!canAdvance(current,index,failed)){stop();return;}go(index+1);if(index===current.steps.length-1)stop();else schedule();},Number($('speed').value));}
function go(next){const requested=clamp(next,0,current.steps.length-1);index=failed&&requested>current.failure.at?current.failure.at:requested;progress=markVisited(progress,current.id,index);selectNode(current.steps[index].to);renderStep();save();}
function renderStep(){renderConnection();const s=current.steps[index];$('lesson-number').textContent=String(index+1).padStart(2,'0');$('step-protocol').textContent=s.protocol;$('step-title').textContent=s.title;$('step-text').textContent=s.text;$('payload').textContent=s.payload;$('step-extra').textContent=s.extra;$('step-label').textContent=`Step ${index+1} of ${current.steps.length}`;$('previous').disabled=index===0;$('next').disabled=!canAdvance(current,index,failed);$('scene-state').textContent=failed?'Failure injected · investigate the evidence':index===current.steps.length-1?'Journey traced · review what you learned':'Following the flow · '+s.title;$('step-dots').replaceChildren(...current.steps.map((s,i)=>{const b=el('button',undefined,'step-dot'+(i<=index?' active':''));b.setAttribute('aria-label',`Step ${i+1}: ${s.title}`);b.setAttribute('aria-current',i===index?'step':'false');b.addEventListener('click',()=>{stop();go(i);});return b;}));model.update({step:index,selected,playing,failed});}
function selectNode(id){selected=id;const n=current.nodes.find(n=>n.id===id);$('node-icon').textContent=n.icon;$('node-type').textContent=n.type+' / '+n.zone.toUpperCase();$('node-title').textContent=n.title;$('node-purpose').textContent=n.purpose;$('node-input').textContent=n.input;$('node-output').textContent=n.output;$('node-why').textContent=n.why;$('node-tip').textContent=n.tip;$('node-tools').replaceChildren(...n.tools.map(t=>el('span',t)));model.update({step:index,selected,playing,failed});if('speechSynthesis'in window){speechSynthesis.cancel();$('speak').textContent='♬ Read explanation';}}
function loadLab(id){stop();current=labs.find(l=>l.id===id)||labs[0];index=0;selected=current.nodes[0].id;failed=false;quizSolved=false;$('lab-title').textContent=current.title;$('lab-level').textContent=current.level;$('lab-description').textContent=current.description;$('failure-intro').textContent=current.failure.title;$('failure-panel').hidden=true;$('inject').disabled=false;$('inject').textContent='⚡ Inject a failure';$('fix-feedback').textContent='';$('quiz-question').textContent=current.quiz.question;$('quiz-feedback').textContent='';$('quiz-feedback').className='';$('quiz-options').replaceChildren(...current.quiz.options.map((text,i)=>{const b=el('button',text,'choice');b.addEventListener('click',()=>{if(quizSolved)return;const correct=i===current.quiz.correct;b.classList.add(correct?'correct':'wrong');$('quiz-feedback').className=correct?'feedback-success':'feedback-error';$('quiz-feedback').textContent=(correct?'Correct. ':'Try again. ')+current.quiz.explanation;if(correct){quizSolved=true;progress=markTask(progress,current.id,'quiz');$('quiz-options').querySelectorAll('button').forEach(n=>n.disabled=true);save();}});return b;}));$('flow-list').replaceChildren(...current.steps.map((s,i)=>{const li=el('li');const b=el('button',`${s.title} — ${s.protocol}`);b.addEventListener('click',()=>{stop();go(i);$('step-title').scrollIntoView({block:'nearest'});});li.append(b,el('small',s.text+' '+s.extra));return li;}));model.setLab(current);selectNode(selected);progress=markVisited(progress,current.id,0);renderStep();save();renderSidebar();}
function renderSidebar(){$('lab-count').textContent=String(labs.length).padStart(2,'0')+' MODELS';$('lab-list').replaceChildren(...labs.map(l=>{const b=el('button',undefined,'lab-link'+(l.id===current.id?' active':''));b.setAttribute('aria-current',l.id===current.id?'true':'false');const text=el('span');text.append(el('strong',l.title),el('small',l.level));b.append(el('span',l.icon,'lab-symbol'),text);if(isComplete(progress,l))b.append(el('span','✓','done'));b.addEventListener('click',()=>loadLab(l.id));return b;}));}
function renderProgress(){const count=labs.filter(l=>isComplete(progress,l)).length;$('progress-count').textContent=`${count} / ${labs.length}`;$('progress-bar').style.width=`${count/labs.length*100}%`;$('storage-status').textContent=storageAvailable?'Progress saves automatically in this browser.':'Browser storage is unavailable. Progress lasts for this session; download it to keep a record.';if(!$('page-path').hidden)renderPath();renderSidebar();}
function showPage(page){stop();setWorldActive(page==='world');for(const id of ['lab','library','path','study','projects','world'])$('page-'+id).hidden=id!==page;document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});if(page==='path'){renderPath();renderRoadmap();}if(page==='library')renderLibrary();if(page==='lab')model.dirty=true;}
function openLab(id){showPage('lab');loadLab(id);$('lab-title').setAttribute('tabindex','-1');$('lab-title').focus({preventScroll:true});window.scrollTo({top:0});}
function renderPath(){$('path-list').replaceChildren(...labs.map(l=>{const r=getRecord(progress,l.id);const card=el('article',undefined,'path-item');const body=el('div');body.append(el('h2',l.title),el('p',l.description));const checks=el('div',undefined,'path-checks');const journey=l.steps.every((_,i)=>r.visited.includes(i));for(const [text,done] of [[`Journey ${r.visited.length}/${l.steps.length}`,journey],['Knowledge check',r.quiz],['Recovery exercise',r.repaired]])checks.append(el('span',`${done?'✓':'○'} ${text}`,done?'complete':''));body.append(checks);const b=el('button',isComplete(progress,l)?'Revisit model ↗':'Explore model →','outline');b.addEventListener('click',()=>openLab(l.id));card.append(el('div',l.icon,'path-icon'),body,b);return card;}));}
function renderLibrary(){const result=matchingTopics(topics,$('search').value,$('category-filter').value);$('result-count').textContent=`${result.length} / ${topics.length} areas`;$('empty-results').hidden=result.length>0;$('library-grid').replaceChildren(...result.map(t=>{const card=el('article',undefined,'topic-card');card.append(el('div',t.area.toUpperCase(),'eyebrow'),el('h2',t.title),el('p',t.purpose),el('div',t.flow,'topic-flow'));const details=el('details');details.append(el('summary','Explore skills & practice'));const list=el('ul');t.skills.forEach(s=>list.append(el('li',s)));const tags=el('div',undefined,'tags');t.tools.forEach(s=>tags.append(el('span',s)));details.append(list,tags,el('h4','TRY THIS'),el('p',t.practice),el('h4','WATCH OUT FOR'),el('p',t.pitfall));const b=el('button','Open related 3D model →','outline');b.addEventListener('click',()=>openLab(t.related));const learn=el('button','Learn this topic →','primary');learn.addEventListener('click',()=>openTopic(t.title));card.append(details,learn,b);return card;}));}
function inject(){stop();failed=true;$('failure-panel').hidden=false;$('inject').disabled=true;$('failure-evidence').replaceChildren(el('p',current.failure.evidence,'evidence'));$('fix-feedback').textContent='';$('fix-options').replaceChildren(...current.failure.options.map((text,i)=>{const b=el('button',text,'choice');b.addEventListener('click',()=>{const good=i===current.failure.correct;b.classList.add(good?'correct':'wrong');$('fix-feedback').className=good?'feedback-success':'feedback-error';$('fix-feedback').textContent=good?'Recovered in this simulation. '+current.failure.explanation:'That does not address the evidence safely. Recheck the logs and try another action.';if(good){failed=false;progress=markTask(progress,current.id,'repaired');$('fix-options').querySelectorAll('button').forEach(b=>b.disabled=true);$('inject').textContent='✓ Recovery exercise completed';renderStep();save();}});return b;}));go(current.failure.at);}
$('play').addEventListener('click',()=>{if(playing){stop();return;}if(failed&&index>=current.failure.at){$('fix-feedback').textContent='Resolve the injected failure using the evidence below before continuing.';$('failure-panel').scrollIntoView({block:'nearest'});return;}if(index===current.steps.length-1)go(0);playing=true;$('play').textContent='Ⅱ Pause journey';model.update({playing:true});schedule();});
$('next').addEventListener('click',()=>{stop();if(canAdvance(current,index,failed))go(index+1);});$('previous').addEventListener('click',()=>{stop();go(index-1);});$('speed').addEventListener('change',()=>{if(playing)schedule();});
$('inject').addEventListener('click',inject);$('reset-view').addEventListener('click',()=>model.reset());$('rotate-left').addEventListener('click',()=>model.rotate(-.2));$('rotate-right').addEventListener('click',()=>model.rotate(.2));$('zoom-in').addEventListener('click',()=>model.zoomBy(.1));$('zoom-out').addEventListener('click',()=>model.zoomBy(-.1));
for(const mode of ['2d','3d'])$('view-'+mode).addEventListener('click',()=>{model.setMode(mode);for(const m of ['2d','3d']){$('view-'+m).classList.toggle('selected',m===mode);$('view-'+m).setAttribute('aria-pressed',String(m===mode));}$('rotate-left').disabled=mode==='2d';$('rotate-right').disabled=mode==='2d';});
$('focus-step').addEventListener('click',()=>{model.setFocus(!model.focus);$('focus-step').setAttribute('aria-pressed',String(model.focus));$('focus-step').textContent=model.focus?'Show all connections':'Focus step';});
let modelExpanded=false;$('expand-model').addEventListener('click',()=>{modelExpanded=!modelExpanded;$('architecture-workspace').classList.toggle('expanded',modelExpanded);$('expand-model').setAttribute('aria-expanded',String(modelExpanded));$('expand-model').textContent=modelExpanded?'Exit expanded view':'Expand model';model.dirty=true;});
$('help-button').addEventListener('click',()=>{$('help').hidden=!$('help').hidden;$('help-button').setAttribute('aria-expanded',String(!$('help').hidden));});
$('search').addEventListener('input',renderLibrary);$('category-filter').addEventListener('change',renderLibrary);document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
$('cloud-table').replaceChildren(...cloudServices.map(row=>{const tr=el('tr');row.forEach(text=>tr.append(el('td',text)));return tr;}));
$('export-progress').addEventListener('click',()=>{const report={...progress,topicLearning:learningProgressReport(),exportedAt:new Date().toISOString(),summary:labs.map(l=>({model:l.title,complete:isComplete(progress,l),...getRecord(progress,l.id)}))};const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download='devops-universe-progress.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('reset-progress').addEventListener('click',()=>{if(!resetArmed){resetArmed=true;$('reset-progress').textContent='Click again to confirm reset';$('reset-progress').classList.add('reset-confirm');return;}resetArmed=false;progress=initialProgress();resetLearning();$('reset-progress').textContent='Reset progress';$('reset-progress').classList.remove('reset-confirm');save();loadLab(current.id);});
if(!('speechSynthesis'in window)){$('speak').disabled=true;$('speech-note').textContent='Speech is unavailable in this browser. All explanations are available as text.';}else $('speak').addEventListener('click',()=>{if(speechSynthesis.speaking){speechSynthesis.cancel();$('speak').textContent='♬ Read explanation';return;}const n=current.nodes.find(n=>n.id===selected);const utterance=new SpeechSynthesisUtterance(`${n.title}. ${n.purpose} It receives: ${n.input} It sends: ${n.output} Why it matters: ${n.why} Remember: ${n.tip}`);utterance.rate=.9;utterance.onend=utterance.onerror=()=>{$('speak').textContent='♬ Read explanation';};speechSynthesis.speak(utterance);$('speak').textContent='■ Stop reading';});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();if('speechSynthesis'in window)speechSynthesis.cancel();}});
function renderConnection(){const d=connectionDetails(current,index);const fields=[['RELATIONSHIP',d.kind],['SOURCE',d.sourceName+' · '+d.source],['DESTINATION',d.destinationName+' · '+d.destination],['SOURCE PORT',d.sourcePort],['DESTINATION PORT',d.destinationPort],['PROTOCOL',d.protocol],['ROUTE / BOUNDARY',d.route],['ACCESS DECISION (EXAMPLE)',d.security],['RETURN PATH / CAVEAT',d.response],['EXAMPLE PAYLOAD',d.payload]];$('connection-fields').replaceChildren(...fields.map(([title,value])=>{const group=el('div',undefined,'connection-field');group.append(el('dt',title),el('dd',value));return group;}));$('connection-note').textContent=d.note;}
loadLab(labs[0].id);renderLibrary();initializeWorldUI();$('launch-world').addEventListener('click',()=>showPage('world'));initializeStudy({openLab,showPage});const linkedModel=resolveModel(globalThis.location?.search||'',labs);if(new URLSearchParams(globalThis.location?.search||'').has('world'))showPage('world');else if(linkedModel)openLab(linkedModel);else showPage('study');
